import type { APIRoute } from 'astro'

/**
 * Crawlers request /robots.txt from the domain root; with the /docs build base
 * the page endpoint below is exactly what lands at that root (pages build
 * without the base prefix in dist — only URLs carry it).
 *
 * The sitemap index is generated by Starlight's built-in @astrojs/sitemap into
 * the dist root. Its URLs are canonical on niftyleague.com, so the reference
 * points at the apex copy (served through the /docs proxy); the same file
 * remains reachable directly at /sitemap-index.xml on this host for the Algolia
 * crawler (algolia-config.json).
 */
const robotsTxt = `User-agent: *
Allow: /

Sitemap: https://niftyleague.com/docs/sitemap-index.xml
`

export const GET: APIRoute = () =>
  new Response(robotsTxt, { headers: { 'Content-Type': 'text/plain; charset=utf-8' } })
